const search_query = String($json.search_query || '').trim();
const location = String($json.location || '').trim();

if (!search_query) {
  throw new Error('SEARCH_QUERY_MISSING');
}

if (!location) {
  throw new Error('LOCATION_MISSING');
}

return [{
  json: {
    ...$json,
    search_query,
    location
  }
}];

return items.map(item => {
  const data = item.json;

  return {
    json: {
      name: data.name ?? data.business_name ?? null,
      phone: data.phone ?? data.phone_number ?? null,
      email: data.email ?? null,
      website: data.website ?? data.url ?? null,
      source: data.source ?? 'google_maps'
    }
  };
});
